const rows = $input.all().map(i => i.json).filter(r => r && r.name);
const f = $('When Called by Agent').first().json;
const lookup = !!(f.dish && String(f.dish).trim());
const item = r => ({ section: r.section, name: r.name, description: r.description, unit: r.unit || undefined,
  allergens: r.allergens, diet: r.diet, spicy: r.spicy, contains: r.contains, notes: r.notes || undefined,
  available_from: r.available_from || undefined, available_to: r.available_to || undefined,
  ...(lookup ? { price_thb: r.price_thb, allergen_conflicts: r.allergen_conflicts, contains_conflicts: r.contains_conflicts, diet_ok: r.diet_ok,
                 suits_guest: r.allergen_conflicts.length === 0 && r.contains_conflicts.length === 0 && r.diet_ok } : {}) });
return [{ json: {
  mode: lookup ? 'lookup' : 'search',
  status: rows.length ? 'ok' : (lookup ? 'not_found' : 'no_match'),
  count: rows.length,
  filters: { kind: f.kind || 'any', exclude_allergens: f.exclude_allergens || '', diet: f.diet || '',
             service: f.service || '', date: f.date || 'today', exclude_contains: f.exclude_contains || '', dish: f.dish || '', text: f.text || '' },
  note: lookup
    ? 'Lookup of named items. suits_guest=false means it contains an excluded allergen or ingredient, or does not fit the diet. Cross-contact is possible; the team confirms on arrival.'
    : 'Only these items match the filters. Allergens are from the menu data; cross-contact is possible and the team confirms on arrival.',
  items: rows.map(item),
} }];
